code.usageCode:
import { List, TransactionListAction } from '@useblu/ocean-react';

<List>
  {/* Leva ao detalhe */}
  <TransactionListAction
    title="PagBlu"
    description="Padaria São José"
    caption="Cobrança 10482"
    amount="R$ 15,00"
    onClick={() => navigate('/cobrancas/10482')}
  />
  {/* Ações sobre o item */}
  <TransactionListAction
    title="PagBlu"
    description="Mercado Central"
    amount="R$ 42,00"
    actionType="menu"
    menuActions={[
      { label: 'Reenviar cobrança', onClick: resend },
      { label: 'Cancelar cobrança', onClick: cancel, variant: 'negative' },
    ]}
    showDivider={false}
  />
</List>
